#!/bin/bash
# sweepfmt.sh LOG : compact the orogenSweep output (relief-class rows then uplift-class rows per set)
grep -E "^s[0-9]|channel slope|mountain cells' distance|45 km²: [0-9]+; mountain|largest exit|Hack" $1 | sed -E 's/confluences both >= 45 km²: [0-9]+; mountain [0-9]+ \([0-9]+ %\), hill [0-9]+ \([0-9]+ %\), plain [0-9]+ \([0-9]+ %\); mountain\+hill [0-9]+ %;/c45/; s/per 1000.*//; s/Hack h.*Re p50 sea basins >= 100 km² ([0-9.]+).*/Re \1/; s/rivers to the sea >= 500 km² fed from the ranges: ([0-9]+); largest exit \/ mouth area p25\/p50\/p75/em(\1)/; s/exits >= 10 km² per river.*//; s/.*land [0-9]+ km² \(mountain ([0-9]+).*distance to the front p50\/p90\/p99\/max ([0-9.]+)\/([0-9.]+).*/  mtn \1 km², dist p50\/p90 \2\/\3/; s/; kept hollows/ kept/; s/relief classes m\/h\/p/rc/; s/channel slope p50 //' | paste -sd' ' | sed -E 's/ (s[0-9]+ sigma)/\n\1/g'
